"""Generate native capability entrypoints from the server's action partitions."""

import argparse
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "Server/src"))

from services.registry.capability_catalog import (  # noqa: E402
    CAPABILITIES,
    LEGACY_TOOLS,
    NATIVE_HANDLERS,
)

TARGET = ROOT / "MCPForUnity/Editor/Tools/ToolCapabilities.generated.cs"


def render() -> str:
    lines = [
        "// <auto-generated />",
        "// Run: python tools/generate_tool_capabilities.py",
        "using System;",
        "using System.Collections.Generic;",
        "using System.Threading;",
        "using System.Threading.Tasks;",
        "using Newtonsoft.Json.Linq;",
        "",
        "namespace MCPForUnity.Editor.Tools.Capabilities",
        "{",
        "    internal static class ToolCapabilityCatalog",
        "    {",
        "        internal static readonly string[] LegacyNames = { "
        + ", ".join(json.dumps(name) for name in sorted(LEGACY_TOOLS))
        + " };",
        "        private static readonly Dictionary<string, string> Sources = new Dictionary<string, string>",
        "        {",
    ]
    for capability in CAPABILITIES:
        lines.append(f'            {{ "{capability.name}", "{capability.source}" }},')
    lines += [
        "        };",
        "        internal static string GetSource(string name) => Sources.TryGetValue(name, out var source) ? source : null;",
        "        internal static Func<JObject, BatchActionValidation> GetBatchValidator(Type type)",
        "        {",
    ]
    for capability in CAPABILITIES:
        if capability.source in {"manage_scene", "manage_gameobject"}:
            name = "".join(word.title() for word in capability.name.split("_"))
            lines.append(
                f"            if (type == typeof({name})) return {name}.ValidateBatchAction;"
            )
    lines += ["            return null;", "        }", "    }", ""]
    for capability in CAPABILITIES:
        native, cooperative = NATIVE_HANDLERS[capability.source]
        name = "".join(word.title() for word in capability.name.split("_"))
        lines += [
            f'    [McpForUnityTool("{capability.name}", AutoRegister = false, Group = "{capability.group}",',
            f"        DisplayName = {json.dumps(capability.title)}, Description = {json.dumps(capability.description)})]",
            f"    public static class {name}",
            "    {",
            "        private static readonly string[] Actions = { "
            + ", ".join(json.dumps(action) for action in capability.native_actions)
            + " };",
        ]
        if capability.source in {"manage_scene", "manage_gameobject"}:
            lines += [
                "        internal static BatchActionValidation ValidateBatchAction(JObject parameters) =>",
                f"            ToolCapabilityDispatch.ValidateBatch(parameters, Actions, {native}.ValidateBatchAction);",
            ]
        if cooperative:
            lines += [
                "        public static Task<object> HandleCommand(JObject parameters, CancellationToken cancellationToken) =>",
                f"            ToolCapabilityDispatch.InvokeAsync(parameters, Actions, {native}.HandleCommand, cancellationToken);",
                "        public static object HandleCommand(JObject parameters) => HandleCommand(parameters, CancellationToken.None);",
            ]
        else:
            lines += [
                "        public static object HandleCommand(JObject parameters) =>",
                f"            ToolCapabilityDispatch.Invoke(parameters, Actions, {native}.HandleCommand);",
            ]
        lines += ["    }", ""]
    return "\n".join([*lines, "}", ""])


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    expected = render()
    if args.check:
        if not TARGET.is_file() or TARGET.read_text(encoding="utf-8") != expected:
            print("Native capability catalog is stale. Run tools/generate_tool_capabilities.py")
            return 1
    else:
        TARGET.write_text(expected, encoding="utf-8", newline="\n")
    print(f"Verified {len(CAPABILITIES)} native capability entrypoints.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
